CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 INTEGER COLLATE NOCASE, c1 VARCHAR(10) DEFAULT 'd');
INSERT OR IGNORE INTO t0(c0, c1) VALUES(NULL, -16.7);
INSERT OR IGNORE INTO t0(c0, c1) VALUES(x'39', NULL);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 INTEGER UNIQUE, c1 ANY DEFAULT 'd', c2 REAL, c3 INTEGER UNIQUE, c4 INTEGER COLLATE NOCASE, ref INTEGER REFERENCES t0(id)) STRICT;
SELECT length('-7'), upper('-7'), lower('-7'), substr('-7', 1, 0), instr('-7', 'a%b'), replace('-7', 'e', ''), trim('-7'), ltrim('-7', 'ab'), hex('-7'), quote('-7'), unicode('-7'), '-7' LIKE 'A%', '-7' GLOB 'a*', char(65, 642), '-7' || 'a%b', '-7' < 'a%b', '-7' = 'a%b' COLLATE NOCASE;
SELECT length('xi'), upper('xi'), lower('xi'), substr('xi', 0, 0), instr('xi', 'NULL'), replace('xi', '', '_'), trim('xi'), ltrim('xi', 'ab'), hex('xi'), quote('xi'), unicode('xi'), 'xi' LIKE 'A%', 'xi' GLOB 'a*', char(85, 838), 'xi' || 'NULL', 'xi' < 'NULL', 'xi' = 'NULL' COLLATE NOCASE;
SELECT length('rho'), upper('rho'), lower('rho'), substr('rho', 2, 0), instr('rho', '42'), replace('rho', 'a', ''), trim('rho'), ltrim('rho', 'ab'), hex('rho'), quote('rho'), unicode('rho'), 'rho' LIKE 'a%', 'rho' GLOB 'a*', char(89, 503), 'rho' || '42', 'rho' < '42', 'rho' = '42' COLLATE NOCASE;
SELECT length('beta'), upper('beta'), lower('beta'), substr('beta', -3, 1), instr('beta', 'señor'), replace('beta', 'e', '_'), trim('beta'), ltrim('beta', 'ab'), hex('beta'), quote('beta'), unicode('beta'), 'beta' LIKE '%', 'beta' GLOB '*[a-m]*', char(74, 448), 'beta' || 'señor', 'beta' < 'señor', 'beta' = 'señor' COLLATE NOCASE;
SELECT id, (SELECT count(*) FROM t1 WHERE t1.id <= t0.id) FROM t0 ORDER BY id, id;
SELECT id FROM t0 WHERE id NOT IN (SELECT id FROM t1 WHERE -(id)) ORDER BY id;
SELECT id FROM t0 x WHERE EXISTS (SELECT 1 FROM t1 y WHERE y.id = x.id + 2) ORDER BY id;
SELECT c0 FROM t0 INTERSECT SELECT ref FROM t1 ORDER BY 1 LIMIT 14 OFFSET 3;
